(function () {
  function _object_from_string(v) {
    if (v !== null && typeof v === "object" && !Array.isArray(v)) {
      return v;
    }
    if (typeof v === "string") {
      try {
        const parsed = JSON.parse(v);
        if (parsed !== null && typeof parsed === "object" && !Array.isArray(parsed)) {
          return parsed;
        }
      } catch {
        /* fall through */
      }
    }
    throw new Error("expected object");
  }

  function _object_to_string(v) {
    return JSON.stringify(_object_from_string(v));
  }

  return { _object_from_string, _object_to_string };
})
